// 4. Trains Search
app.get('/api/trains/search', async (req, res) => {
  const q = String(req.query.q || '').trim();
  if (q.length < 2 || q.length > 40) return bad(res, 'Query must be 2-40 characters.');

  const rcRes = await fetchRC(`/trains/search?q=${encodeURIComponent(q)}`, 604_800_000);
  if (rcRes.code === 200 && rcRes.body?.success) return res.status(200).json(rcRes.body);
  send(res, rcRes);
});

// 5. Stations Search
