// 6. Station Live Board
app.get('/api/station/:code/live', async (req, res) => {
  const code = req.params.code.toUpperCase();
  if (!/^[A-Za-z]{1,6}$/.test(code)) return bad(res, 'Invalid station code.');

  const rcRes = await fetchRC(`/stations/${code}/live`, 604_800_000);
  if (rcRes.code === 200 && rcRes.body?.success) return res.status(200).json(rcRes.body);
  send(res, rcRes);
});

// 7. Station Details by Code
app.get('/api/station/:code', async (req, res) => {
  const code = req.params.code.toUpperCase();
  if (!/^[A-Za-z]{1,6}$/.test(code)) return bad(res, 'Invalid station code.');

  const rcRes = await fetchRC(`/stations/${code}`, 604_800_000);
  if (rcRes.code === 200 && rcRes.body?.success) return res.status(200).json(rcRes.body);
  send(res, rcRes);
});

app.use('/api', (q, res) => res.status(404).json(err(404, 'NOT_FOUND', 'Unknown endpoint.')));
app.listen(process.env.PORT || 3000, () => console.log('RailCore Only on http://localhost:' + (process.env.PORT || 3000)));
